\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ══ Color Theme: Warm Advocacy (Dark Background) ══
\definecolor{primary}{HTML}{92400E}       % deep amber/brown
\definecolor{secondary}{HTML}{DC2626}     % warm red
\definecolor{accent}{HTML}{F59E0B}        % golden amber
\definecolor{bgposter}{HTML}{1C1917}      % warm dark charcoal
\definecolor{cardbg}{HTML}{292524}        % warm dark card
\definecolor{cardbgalt}{HTML}{2A2018}     % warm amber-tinted dark
\definecolor{cardbgred}{HTML}{2D2020}     % warm red-tinted dark
\definecolor{titlebar}{HTML}{7C2D12}      % deep burnt orange
\definecolor{textlight}{HTML}{F5F5F4}     % warm white
\definecolor{textmuted}{HTML}{D6D3D1}     % warm light gray
\definecolor{textdim}{HTML}{A8A29E}       % warm gray
\definecolor{stathighlight}{HTML}{3B2413}  % deep warm brown for stat bg
\definecolor{goldhighlight}{HTML}{3D2E0A}  % deep gold for stat bg
\definecolor{redhighlight}{HTML}{3B1A1A}   % deep red for stat bg
\definecolor{actiongreen}{HTML}{16A34A}   % green for CTA
\definecolor{stripeRed}{HTML}{EF4444}     % bright red stripe
\definecolor{stripeGold}{HTML}{FBBF24}    % bright gold stripe
\definecolor{stripeOrange}{HTML}{F97316}  % bright orange stripe
\definecolor{stripeAmber}{HTML}{D97706}   % deep amber stripe

\pagecolor{bgposter}
\color{textlight}

% ══ List styling ══
\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{accent}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=28pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{accent}\bfseries\arabic*.}}

% ══ Card styles for dark background ══
\tcbset{
  warmcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={6pt}{0pt}{stripeOrange},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=cardbgalt,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={accent!40},
    valign=top, drop shadow={opacity=0.25, offset={2mm}{-2mm}},
  },
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbgred,
    borderline west={6pt}{0pt}{stripeRed},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{stripeRed},
    coltitle=stripeRed, colbacktitle=cardbgred,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={stripeRed!40},
    valign=top, drop shadow={opacity=0.25, offset={2mm}{-2mm}},
  },
  goldcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbgalt,
    borderline west={6pt}{0pt}{stripeGold},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{stripeGold},
    coltitle=stripeGold, colbacktitle=cardbgalt,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={stripeGold!40},
    valign=top, drop shadow={opacity=0.25, offset={2mm}{-2mm}},
  },
  ambercard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbgalt,
    borderline west={6pt}{0pt}{stripeAmber},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{stripeAmber},
    coltitle=stripeAmber, colbacktitle=cardbgalt,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={stripeAmber!40},
    valign=top, drop shadow={opacity=0.25, offset={2mm}{-2mm}},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=titlebar,
    borderline west={7pt}{0pt}{accent},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=titlebar,
    toptitle=8pt, bottomtitle=8pt,
    valign=top, drop shadow={opacity=0.3, offset={2mm}{-2mm}},
  },
  actioncard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=cardbgalt,
    borderline west={6pt}{0pt}{actiongreen},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{actiongreen},
    coltitle=actiongreen, colbacktitle=cardbgalt,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=1pt, titlerule style={actiongreen!40},
    valign=top, drop shadow={opacity=0.2},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ════════════════════════════════════════════════════
% ══ TITLE BAR (span=3, rows 0-3) ══
% ════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=titlebar, colframe=titlebar, colupper=textlight,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=20pt, bottom=12pt,
  halign=center, valign=center,
  borderline south={6pt}{0pt}{accent},
  drop shadow={opacity=0.4, offset={3mm}{-3mm}}
]{name=title, column=1, span=3, between=top and row3}{
  {\fontsize{82}{98}\selectfont\bfseries\color{textlight} Hunger Doesn't Wait}\\[8pt]
  {\fontsize{82}{98}\selectfont\bfseries\color{accent} --- Together We Can End It}\\[16pt]
  {\fontsize{34}{42}\selectfont\color{textmuted} 48 million Americans face hunger --- but a united network is fighting back}
}

% ════════════════════════════════════════════════════
% ══ HERO STAT BANNER (span=3, rows 3-6) ══
% ════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=bgposter, boxrule=0pt, arc=0pt,
  left=20pt, right=20pt, top=10pt, bottom=10pt,
  valign=center,
]{name=stats, column=1, span=3, between=row3 and row6}{
  \centering
  % Stat 1: 48 Million
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{stripeRed!60}{redhighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{68}{82}\selectfont\bfseries\color{stripeRed} 48 Million}\\[6pt]
      {\fontsize{26}{32}\selectfont\color{textmuted} People Facing Hunger}\\[2pt]
      {\fontsize{22}{28}\selectfont\color{textdim} across the United States}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  % Stat 2: 5.7 Billion
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{stripeGold!60}{goldhighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{68}{82}\selectfont\bfseries\color{stripeGold} 5.7 Billion}\\[6pt]
      {\fontsize{26}{32}\selectfont\color{textmuted} Meals Distributed}\\[2pt]
      {\fontsize{22}{28}\selectfont\color{textdim} through the network}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  % Stat 3: $1 = 10 Meals
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{stripeOrange!60}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{64}{78}\selectfont\bfseries\color{stripeOrange} \$1 = 10 Meals}\\[6pt]
      {\fontsize{26}{32}\selectfont\color{textmuted} Donation Impact}\\[2pt]
      {\fontsize{22}{28}\selectfont\color{textdim} every dollar provides meals}\vspace{8pt}%
    }}
  \end{minipage}
}

% ════════════════════════════════════════════════════
% ══ ROW A: Crisis | Impact | Unite (rows 6-12) ══
% ════════════════════════════════════════════════════

% ── Column 1: The Hunger Crisis ──
\posterbox[redcard, title={The Hunger Crisis}
]{name=crisis, column=1, between=row6 and row12}{
  \fontsize{32}{42}\selectfont\color{textlight}
  \begin{itemize}[itemsep=14pt]
    \item {\color{textlight}\textbf{48 million people}} face hunger in the U.S.
    \item {\color{textlight}\textbf{14 million children}} affected nationwide
    \item Families in every state --- urban and rural alike
  \end{itemize}
  \vspace{10pt}
  \colorbox{stripeRed!20}{\parbox{0.90\linewidth}{%
    \centering\vspace{6pt}%
    {\fontsize{28}{36}\selectfont\color{stripeRed}\textbf{This is not just a statistic ---}}\\
    {\fontsize{28}{36}\selectfont\color{stripeRed}\textbf{it's our neighbors, classmates,}}\\
    {\fontsize{28}{36}\selectfont\color{stripeRed}\textbf{and community members.}}%
    \vspace{6pt}%
  }}
}

% ── Column 2: Our Collective Impact ──
\posterbox[goldcard, title={Our Collective Impact}
]{name=impact, column=2, between=row6 and row12}{
  \fontsize{32}{42}\selectfont\color{textlight}
  \begin{itemize}[itemsep=12pt]
    \item {\color{stripeGold}\textbf{5.7 billion}} meals distributed
    \item {\color{stripeGold}\textbf{4.3 billion lbs}} food rescued
    \item {\color{stripeGold}\textbf{60,000+}} free food programs
    \item {\color{stripeGold}\textbf{200+}} food banks across all 50 states
  \end{itemize}
  \vspace{10pt}
  \colorbox{stripeGold!20}{\parbox{0.90\linewidth}{%
    \centering\vspace{6pt}%
    {\fontsize{26}{34}\selectfont\color{stripeGold}\textit{Rescued food --- perfectly good food that}}\\
    {\fontsize{26}{34}\selectfont\color{stripeGold}\textit{might otherwise go to waste --- reaches}}\\
    {\fontsize{26}{34}\selectfont\color{stripeGold}\textit{people who need it most.}}%
    \vspace{6pt}%
  }}
}

% ── Column 3: How We Unite Communities ──
\posterbox[warmcard, title={How We Unite Communities}
]{name=unite, column=3, between=row6 and row12}{
  \fontsize{30}{40}\selectfont\color{textlight}
  \begin{itemize}[itemsep=10pt, leftmargin=22pt]
    \item {\color{accent}\textbf{Research-Driven}} --- Listening to neighbors, shaping real solutions
    \item {\color{accent}\textbf{Local Wisdom}} --- Community leaders driving national action
    \item {\color{accent}\textbf{Nationwide Scale}} --- Moving food quickly and reliably
    \item {\color{accent}\textbf{Nutrition First}} --- Making nutritious food accessible to all
  \end{itemize}
  \vspace{8pt}
  \colorbox{accent!20}{\parbox{0.90\linewidth}{%
    \vspace{4pt}%
    {\fontsize{24}{30}\selectfont\color{accent}\textit{``They give you groceries and recipes.}}\\
    {\fontsize{24}{30}\selectfont\color{accent}\textit{I've learned how to use whole foods}}\\
    {\fontsize{24}{30}\selectfont\color{accent}\textit{and learned different options.''}}\\
    {\fontsize{22}{28}\selectfont\color{textdim} --- Kaycee, Washington}%
    \vspace{4pt}%
  }}
}

% ════════════════════════════════════════════════════
% ══ ROW B: Take Action (rows 12-18) ══
% ════════════════════════════════════════════════════

% ── Column 1: Donate ──
\posterbox[actioncard, title={\fontsize{36}{44}\selectfont Donate}
]{name=donate, column=1, between=row12 and row15}{
  \fontsize{30}{40}\selectfont\color{textlight}
  {\fontsize{52}{62}\selectfont\bfseries\color{stripeOrange} \$1 = 10 Meals}\\[8pt]
  Every dollar provides at least 10 meals.\\[4pt]
  Gifts are \textbf{matched} for a limited time.
  \vspace{6pt}
  \colorbox{stripeOrange!20}{\parbox{0.92\linewidth}{%
    \centering\vspace{4pt}%
    {\fontsize{26}{32}\selectfont\color{stripeOrange}\textbf{Move fresh food to}}\\
    {\fontsize{26}{32}\selectfont\color{stripeOrange}\textbf{neighbors fast}}%
    \vspace{4pt}%
  }}
}

% ── Column 2: Advocate ──
\posterbox[actioncard, title={\fontsize{36}{44}\selectfont Advocate}
]{name=advocate, column=2, between=row12 and row15}{
  \fontsize{30}{40}\selectfont\color{textlight}
  Urge lawmakers to support\\[4pt]
  community organizations and\\[4pt]
  government programs that\\[4pt]
  help neighbors facing hunger.
  \vspace{8pt}
  \colorbox{secondary!20}{\parbox{0.92\linewidth}{%
    \centering\vspace{4pt}%
    {\fontsize{26}{32}\selectfont\color{secondary}\textbf{Your voice can}}\\
    {\fontsize{26}{32}\selectfont\color{secondary}\textbf{change policy}}%
    \vspace{4pt}%
  }}
}

% ── Column 3: Fundraise ──
\posterbox[actioncard, title={\fontsize{36}{44}\selectfont Fundraise}
]{name=fundraise, column=3, between=row12 and row15}{
  \fontsize{30}{40}\selectfont\color{textlight}
  Inspire your community\\[4pt]
  to come together and\\[4pt]
  make a collective\\[4pt]
  difference.
  \vspace{8pt}
  \colorbox{accent!20}{\parbox{0.92\linewidth}{%
    \centering\vspace{4pt}%
    {\fontsize{26}{32}\selectfont\color{accent}\textbf{Together we are}}\\
    {\fontsize{26}{32}\selectfont\color{accent}\textbf{stronger}}%
    \vspace{4pt}%
  }}
}

% ── Volunteer (span=2, rows 15-18) ──
\posterbox[actioncard, title={\fontsize{36}{44}\selectfont Volunteer}
]{name=volunteer, column=1, span=2, between=row15 and row18}{
  \fontsize{30}{40}\selectfont\color{textlight}
  Sorting, packing, and distributing food takes many hands --- \textbf{including yours}.\\[6pt]
  Join thousands of volunteers making a difference in your community.
  \vspace{6pt}
  \colorbox{actiongreen!20}{\parbox{0.60\linewidth}{%
    \centering\vspace{4pt}%
    {\fontsize{26}{32}\selectfont\color{actiongreen}\textbf{Every hour you give feeds families}}%
    \vspace{4pt}%
  }}
}

% ── Every Action Counts sidebar (col 3, rows 15-18) ──
\posterbox[highlightcard, title={Every Action Counts}
]{name=everyaction, column=3, between=row15 and row18}{
  \fontsize{28}{36}\selectfont\color{textlight}
  \begin{itemize}[itemsep=8pt, leftmargin=20pt]
    \item {\color{accent}\textbf{4.3B lbs}} food rescued
    \item {\color{accent}\textbf{200+}} food banks
    \item {\color{accent}\textbf{60,000+}} programs
    \item Serving {\color{accent}\textbf{all 50 states}} + Puerto Rico
  \end{itemize}
}

% ════════════════════════════════════════════════════
% ══ BOTTOM CTA BAR (span=3, rows 18-20) ══
% ════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=titlebar, colframe=titlebar, colupper=textlight,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=10pt, bottom=10pt,
  halign=center, valign=center,
  borderline north={4pt}{0pt}{accent},
  drop shadow={opacity=0.3, offset={2mm}{2mm}}
]{name=bottomcta, column=1, span=3, between=row18 and bottom}{
  {\fontsize{48}{58}\selectfont\bfseries\color{accent} Food Rescue Cannot Wait.}\\[8pt]
  {\fontsize{36}{44}\selectfont\color{textmuted} When communities unite, an America without hunger is within reach.}\\[4pt]
  {\fontsize{32}{40}\selectfont\color{textlight} \textbf{Donate} \color{textdim}$\cdot$ \textbf{Advocate} \color{textdim}$\cdot$ \textbf{Fundraise} \color{textdim}$\cdot$ \textbf{Volunteer}}
}

\end{tcbposter}
\end{document}

